begin;

do $avuhz$
declare
  v_auth_user_count bigint;
  v_known_synthetic_user_count bigint;
  v_canonical_tenant_bound_user_count bigint;
  v_target_count bigint;
  v_target_bcrypt_like_count bigint;
  v_target_password_null_count bigint;
  v_target_tenant_bound_count bigint;
  v_target_provider_metadata_exact_count bigint;
  v_target_user_metadata_exact_count bigint;
  v_target_email_identity_count bigint;
  v_session_count bigint;
  v_refresh_token_count bigint;
  v_rows bigint;
begin
  select count(*) into v_auth_user_count from auth.users;
  select count(*) into v_known_synthetic_user_count from auth.users where email = 'avuhz-development-synthetic@example.invalid';
  select count(*) into v_canonical_tenant_bound_user_count from auth.users where raw_app_meta_data ? 'avuhz_tenant_id';
  select
    count(*),
    count(*) filter (where encrypted_password is not null and length(encrypted_password) = 60 and encrypted_password like '$2%'),
    count(*) filter (where encrypted_password is null),
    count(*) filter (where raw_app_meta_data ? 'avuhz_tenant_id'),
    count(*) filter (where raw_app_meta_data = '{"provider":"email","providers":["email"]}'::jsonb),
    count(*) filter (where coalesce(raw_user_meta_data, '{}'::jsonb) = '{}'::jsonb)
  into
    v_target_count,
    v_target_bcrypt_like_count,
    v_target_password_null_count,
    v_target_tenant_bound_count,
    v_target_provider_metadata_exact_count,
    v_target_user_metadata_exact_count
  from auth.users
  where email = 'avuhz-implementation-handoff-provider-adapter-development@example.invalid';
  select count(*) into v_target_email_identity_count
  from auth.identities as i
  join auth.users as u on u.id = i.user_id
  where u.email = 'avuhz-implementation-handoff-provider-adapter-development@example.invalid' and i.provider = 'email';
  select count(*) into v_session_count from auth.sessions;
  select count(*) into v_refresh_token_count from auth.refresh_tokens;

  if v_auth_user_count <> 2
     or v_known_synthetic_user_count <> 1
     or v_canonical_tenant_bound_user_count <> 1
     or v_target_count <> 1
     or v_target_bcrypt_like_count <> 1
     or v_target_password_null_count <> 0
     or v_target_tenant_bound_count <> 0
     or v_target_provider_metadata_exact_count <> 1
     or v_target_user_metadata_exact_count <> 1
     or v_target_email_identity_count <> 1
     or v_session_count <> 0
     or v_refresh_token_count <> 0 then
    raise exception 'AVUHZ_PROVIDER_ADAPTER_PASSWORD_HASH_CORRECTION_PREFLIGHT_FAILED';
  end if;

  update auth.users
  set encrypted_password = null
  where email = 'avuhz-implementation-handoff-provider-adapter-development@example.invalid'
    and encrypted_password is not null
    and length(encrypted_password) = 60
    and encrypted_password like '$2%';
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'AVUHZ_PROVIDER_ADAPTER_PASSWORD_HASH_CORRECTION_ROWCOUNT_FAILED';
  end if;

  select
    count(*),
    count(*) filter (where encrypted_password is not null and length(encrypted_password) = 60 and encrypted_password like '$2%'),
    count(*) filter (where encrypted_password is null),
    count(*) filter (where raw_app_meta_data ? 'avuhz_tenant_id'),
    count(*) filter (where raw_app_meta_data = '{"provider":"email","providers":["email"]}'::jsonb),
    count(*) filter (where coalesce(raw_user_meta_data, '{}'::jsonb) = '{}'::jsonb)
  into
    v_target_count,
    v_target_bcrypt_like_count,
    v_target_password_null_count,
    v_target_tenant_bound_count,
    v_target_provider_metadata_exact_count,
    v_target_user_metadata_exact_count
  from auth.users
  where email = 'avuhz-implementation-handoff-provider-adapter-development@example.invalid';
  select count(*) into v_auth_user_count from auth.users;
  select count(*) into v_known_synthetic_user_count from auth.users where email = 'avuhz-development-synthetic@example.invalid';
  select count(*) into v_canonical_tenant_bound_user_count from auth.users where raw_app_meta_data ? 'avuhz_tenant_id';
  select count(*) into v_target_email_identity_count
  from auth.identities as i
  join auth.users as u on u.id = i.user_id
  where u.email = 'avuhz-implementation-handoff-provider-adapter-development@example.invalid' and i.provider = 'email';
  select count(*) into v_session_count from auth.sessions;
  select count(*) into v_refresh_token_count from auth.refresh_tokens;

  if v_auth_user_count <> 2
     or v_known_synthetic_user_count <> 1
     or v_canonical_tenant_bound_user_count <> 1
     or v_target_count <> 1
     or v_target_bcrypt_like_count <> 0
     or v_target_password_null_count <> 1
     or v_target_tenant_bound_count <> 0
     or v_target_provider_metadata_exact_count <> 1
     or v_target_user_metadata_exact_count <> 1
     or v_target_email_identity_count <> 1
     or v_session_count <> 0
     or v_refresh_token_count <> 0 then
    raise exception 'AVUHZ_PROVIDER_ADAPTER_PASSWORD_HASH_CORRECTION_POSTCONDITION_FAILED';
  end if;
end
$avuhz$;

commit;
